export function amazonPickToCatalogItem(p: AmazonPick): CatalogItem {
  const groups = [...new Set([GROUP[p.category], ...(p.alsoIn ?? []).map((c) => GROUP[c])])].filter(Boolean) as SourceGroupId[];
  return {
    id: p.id,
    title: p.title,
    blurb: p.blurb,
    sourceName: p.brand,
    href: amazonProductUrl(p.asin),
    rel: 'sponsored nofollow noopener',
    affiliate: true,
    hideOnPaid: true,
    programId: 'amazon',
    category: p.category,
    alsoIn: p.alsoIn,
    image: `/directory/photos/${p.id}-960.webp`,
    imageKind: 'photo',
    priceLabel: 'See price',
    offerLabel: 'On Amazon',
    ctaLabel: 'Check listing',
    ctaKind: 'listing',
    groups,
    kind: 'partner',
    origin: 'directory',
    usBadge: p.us || undefined,
  };
}

export function amazonCatalogItems(): CatalogItem[] {
  return amazonPicks.map(amazonPickToCatalogItem);
}
